  (id, generic_name, brand_names, drug_class, uses, side_effects, interactions, contraindications, dosage_notes, pregnancy_category, pregnancy_category_system, otc, controlled, source_reference, source_url, reviewed_by, reviewed_at)
VALUES
  ('d59','Glibenclamide (Glyburide)','Daonil, Euglucon','Sulphonylurea','Type 2 diabetes mellitus','Hypoglycemia (may be prolonged), weight gain, GI upset, rare cholestasis','Alcohol, beta-blockers (mask hypoglycemia), fluconazole, sulphonamides, NSAIDs','Type 1 diabetes, diabetic ketoacidosis, severe renal/hepatic impairment, pregnancy, breastfeeding','Adults: start 2.5-5 mg daily with breakfast, max 15 mg/day. High hypoglycemia risk in the elderly — avoid or use lowest dose.','C','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d60','Gliclazide','Diamicron, Glizid','Sulphonylurea','Type 2 diabetes mellitus','Hypoglycemia, weight gain, GI upset, rare blood dyscrasias','Alcohol, beta-blockers, fluconazole, NSAIDs, warfarin','Type 1 diabetes, ketoacidosis, severe renal/hepatic impairment, pregnancy','Adults: 40-80 mg daily up to 160 mg twice daily with meals; modified-release 30-120 mg once daily with breakfast.','C','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d61','Insulin (Soluble/Regular)','Actrapid, Humulin R','Short-acting insulin','Type 1 and type 2 diabetes, diabetic emergencies (IV), perioperative control','Hypoglycemia, injection site lipohypertrophy, weight gain','Beta-blockers (mask hypoglycemia), corticosteroids/thiazides (raise glucose), alcohol','Hypoglycemia; hypersensitivity to the specific product','Adults: individualised subcutaneously 15-30 min before meals; IV infusion in emergencies. Rotate injection sites. Store per cold-chain.','B','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d62','Insulin (Isophane/NPH)','Insulatard, Humulin N','Intermediate-acting insulin','Basal insulin coverage in type 1 and type 2 diabetes','Hypoglycemia (including nocturnal), weight gain, lipohypertrophy','Beta-blockers, corticosteroids, thiazides, alcohol','Hypoglycemia; hypersensitivity to product','Adults: individualised subcutaneously once or twice daily. Resuspend cloudy insulin gently before use. Do not give IV.','B','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d63','Insulin (Premixed 70/30)','Mixtard 30, Humulin 70/30','Biphasic insulin','Type 2 (and some type 1) diabetes needing basal and prandial coverage','Hypoglycemia, weight gain, lipohypertrophy','Beta-blockers, corticosteroids, thiazides, alcohol','Hypoglycemia; hypersensitivity to product','Adults: individualised subcutaneously, usually twice daily before breakfast and evening meal. Resuspend before use; do not give IV.','B','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d64','Sitagliptin','Januvia, Istavel','DPP-4 inhibitor','Type 2 diabetes (mono- or add-on therapy)','Nasopharyngitis, headache, pancreatitis (rare), arthralgia, hypoglycemia (with sulphonylurea/insulin)','Additive hypoglycemia with sulphonylureas/insulin','Type 1 diabetes, diabetic ketoacidosis, hypersensitivity; caution with history of pancreatitis','Adults: 100 mg once daily. Reduce dose in moderate-to-severe renal impairment (e.g., 50 mg or 25 mg).','B','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d65','Empagliflozin','Jardiance','SGLT2 inhibitor','Type 2 diabetes, heart failure, chronic kidney disease (cardio-renal protection)','Genital/urinary infections, volume depletion, euglycemic diabetic ketoacidosis, dehydration','Diuretics (volume depletion), insulin/sulphonylureas (hypoglycemia)','Type 1 diabetes, diabetic ketoacidosis, severe renal impairment (efficacy limited); withhold during acute illness/surgery','Adults: 10 mg once daily, increase to 25 mg if needed. Counsel on ketoacidosis symptoms and sick-day rules; maintain hygiene/hydration.','C','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d66','Levothyroxine','Eltroxin, Euthyrox','Thyroid hormone','Hypothyroidism, thyroid hormone replacement','Palpitations, tremor, weight loss, insomnia (usually from over-replacement)','Iron, calcium, antacids (reduced absorption), warfarin, oral contraceptives, rifampicin','Untreated thyrotoxicosis, uncorrected adrenal insufficiency, acute MI','Adults: start 50-100 mcg once daily (25 mcg in elderly/cardiac disease); adjust by TSH. Take on empty stomach 30-60 min before breakfast.','A','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d67','Carbimazole','Neo-Mercazole','Antithyroid agent','Hyperthyroidism (Graves disease), pre-radioiodine/surgery preparation','Rash, pruritus, agranulocytosis (rare but serious), hepatotoxicity','Warfarin, digoxin, theophylline','Severe blood disorders; known hypersensitivity; caution in pregnancy (propylthiouracil preferred first trimester)','Adults: initial 15-40 mg daily until euthyroid, then reduce to maintenance 5-15 mg daily. Seek urgent care for sore throat/fever (agranulocytosis).','D','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d68','Prednisolone','Deltacortril, Prednisone','Corticosteroid','Inflammatory/autoimmune conditions, asthma/COPD exacerbations, allergic reactions, immunosuppression','Weight gain, hyperglycemia, hypertension, osteoporosis, mood changes, adrenal suppression, infection risk','NSAIDs (GI bleeding), live vaccines, antidiabetics, warfarin, diuretics (hypokalemia)','Systemic infection without cover, live vaccines while immunosuppressed; caution in diabetes, peptic ulcer, hypertension','Adults: variable 5-60 mg daily depending on indication. Take in the morning with food. Do not stop long courses abruptly — taper.','C','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL);

-- ============================================================
-- PAIN, ANTI-INFLAMMATORY & GOUT (d69 - d78)
