INSERT OR IGNORE INTO drugs
  (id, generic_name, brand_names, drug_class, uses, side_effects, interactions, contraindications, dosage_notes, pregnancy_category, pregnancy_category_system, otc, controlled, source_reference, source_url, reviewed_by, reviewed_at)
VALUES
  ('d69','Diclofenac','Voltaren, Cataflam, Diclomax','NSAID','Musculoskeletal pain, arthritis, dysmenorrhea, post-operative pain','GI irritation/bleeding, cardiovascular risk, renal impairment, fluid retention','Warfarin, other NSAIDs/aspirin, ACE inhibitors/ARBs, lithium, methotrexate','Active peptic ulcer/GI bleeding, severe heart failure, established cardiovascular disease, third-trimester pregnancy, severe renal impairment','Adults: 50 mg 2-3 times daily or 75 mg twice daily, max 150 mg/day. Take with food. Use lowest effective dose for shortest time.','C','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d70','Naproxen','Naprosyn, Aleve','NSAID','Arthritis, musculoskeletal pain, gout, dysmenorrhea','GI bleeding, dyspepsia, fluid retention, renal impairment, headache','Warfarin, aspirin/other NSAIDs, ACE inhibitors/ARBs, lithium, methotrexate','Active GI ulcer/bleeding, severe heart failure, severe renal impairment, third-trimester pregnancy','Adults: 250-500 mg twice daily, max 1000 mg/day. Take with food. Preferred NSAID where cardiovascular risk is a concern.','C','US-FDA (legacy)',1,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d71','Celecoxib','Celebrex','COX-2 selective NSAID','Osteoarthritis, rheumatoid arthritis, acute pain where GI risk is a concern','Dyspepsia (less than non-selective NSAIDs), cardiovascular risk, edema, renal impairment','Warfarin, ACE inhibitors/ARBs, fluconazole (raises levels), lithium','Sulphonamide allergy, active GI bleeding, severe heart failure, established cardiovascular disease, third-trimester pregnancy','Adults: 100-200 mg once or twice daily. Use lowest effective dose for shortest duration. Assess cardiovascular risk.','C','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d72','Tramadol','Ultram, Tramal','Opioid analgesic (weak mu-agonist)','Moderate to moderately severe pain','Nausea, dizziness, constipation, drowsiness, seizures, serotonin syndrome, dependence','SSRIs/SNRIs/MAOIs (serotonin syndrome), carbamazepine, warfarin, CNS depressants, alcohol','Uncontrolled epilepsy, concurrent/recent MAOI use, severe respiratory depression, acute intoxication with CNS depressants','Adults: 50-100 mg every 4-6 hours, max 400 mg/day. Controlled substance — risk of dependence. Reduce in elderly and renal/hepatic impairment.','C','US-FDA (legacy)',0,1,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d73','Codeine','Codeine phosphate','Opioid analgesic','Mild to moderate pain, cough suppression, antidiarrheal (adjunct)','Constipation, drowsiness, nausea, dependence, respiratory depression','CNS depressants, alcohol, MAOIs, CYP2D6 inhibitors','Children under 12, breastfeeding, ultra-rapid CYP2D6 metabolizers, respiratory depression, acute asthma','Adults: 30-60 mg every 4-6 hours, max 240 mg/day. Controlled substance. Avoid in children under 12 (variable metabolism).','C','US-FDA (legacy)',0,1,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d74','Morphine','MST Continus, Oramorph','Strong opioid analgesic','Severe acute and chronic pain, cancer pain, palliative care','Respiratory depression, constipation, sedation, nausea, dependence, miosis','CNS depressants, benzodiazepines, alcohol, MAOIs','Acute respiratory depression, paralytic ileus, acute severe asthma, raised intracranial pressure (caution)','Adults: individualised; immediate-release 5-10 mg every 4 hours titrated to effect. Controlled substance. Co-prescribe a laxative.','C','US-FDA (legacy)',0,1,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d75','Allopurinol','Zyloric, Zyloprim','Xanthine oxidase inhibitor','Chronic gout prophylaxis, hyperuricemia, tumor lysis prevention','Rash, hypersensitivity syndrome (SJS/TEN — rare), GI upset, raised liver enzymes','Azathioprine/mercaptopurine (severe toxicity), warfarin, ampicillin (rash), thiazides','Acute gout attack (do not start during); known hypersensitivity — stop at first sign of rash','Adults: start 100 mg daily, titrate to urate target, usual 300 mg daily. Do not start during an acute attack. Maintain hydration.','C','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d76','Colchicine','Colcrys, Colchicine','Anti-gout agent','Acute gout attacks, gout flare prophylaxis, familial Mediterranean fever','Diarrhea, nausea, vomiting, myelosuppression and neuromyopathy in overdose/renal impairment','CYP3A4/P-gp inhibitors (macrolides, azoles, verapamil — toxicity), statins','Severe renal or hepatic impairment with P-gp/CYP3A4 inhibitors; blood dyscrasias','Adults: acute gout 500 mcg 2-3 times daily (max ~6 mg/course); prophylaxis 500 mcg once or twice daily. Narrow safety margin — do not exceed.','C','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d77','Ibuprofen/Paracetamol combination','Combiflam, Brufen Plus','NSAID/analgesic combination','Moderate pain with inflammation (dental, musculoskeletal, headache)','GI irritation, as for ibuprofen and paracetamol; liver injury with paracetamol overdose','Warfarin, other NSAIDs, ACE inhibitors/ARBs, alcohol','Active peptic ulcer, severe hepatic impairment, third-trimester pregnancy, NSAID hypersensitivity','Adults: one tablet (typically ibuprofen 400 mg/paracetamol 325-500 mg) up to three times daily with food. Mind total paracetamol from all sources (max 4 g/day).','C','US-FDA (legacy)',1,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d78','Aspirin (analgesic dose)','Aspirin, Disprin','NSAID/analgesic','Mild-to-moderate pain, fever, inflammation (adult use)','GI irritation/bleeding, tinnitus (high dose), bronchospasm in sensitive patients','Anticoagulants, other NSAIDs, methotrexate, corticosteroids','Children under 16 (Reye syndrome), active peptic ulcer/bleeding, aspirin/NSAID hypersensitivity, third-trimester pregnancy','Adults: 300-600 mg every 4-6 hours, max 4 g/day. Take with or after food. Not for analgesia in children under 16.','D','US-FDA (legacy)',1,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL);

-- ============================================================
-- MENTAL HEALTH & NEUROLOGY (d79 - d93)
-- ============================================================
INSERT OR IGNORE INTO drugs
  (id, generic_name, brand_names, drug_class, uses, side_effects, interactions, contraindications, dosage_notes, pregnancy_category, pregnancy_category_system, otc, controlled, source_reference, source_url, reviewed_by, reviewed_at)
VALUES
  ('d79','Amitriptyline','Elavil, Tryptanol','Tricyclic antidepressant','Depression, neuropathic pain, migraine prophylaxis, nocturnal enuresis','Sedation, dry mouth, constipation, urinary retention, weight gain, QT prolongation, arrhythmia in overdose','MAOIs (avoid), SSRIs, tramadol, anticholinergics, QT-prolonging drugs, alcohol','Recent MI, arrhythmias/heart block, severe hepatic impairment, concurrent/recent MAOI use, mania','Adults: depression 25-75 mg at night, titrate; neuropathic pain 10-25 mg at night. Highly toxic in overdose. Taper on stopping.','C','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d80','Fluoxetine','Prozac, Fludac','SSRI antidepressant','Depression, OCD, bulimia, panic disorder','Nausea, insomnia, sexual dysfunction, anxiety, hyponatremia, increased suicidality risk in young adults','MAOIs (avoid, serotonin syndrome), tramadol, NSAIDs/anticoagulants (bleeding), triptans, long half-life delays switches','Concurrent/recent MAOI use, mania','Adults: 20 mg once daily in the morning, up to 60 mg. Onset over 2-4 weeks. Long half-life — allow washout before an MAOI. Taper to stop.','C','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d81','Sertraline','Zoloft, Serlift','SSRI antidepressant','Depression, anxiety disorders, OCD, PTSD, panic disorder','Nausea, diarrhea, insomnia, sexual dysfunction, hyponatremia, increased suicidality risk in young adults','MAOIs (avoid), NSAIDs/anticoagulants (bleeding), tramadol, triptans, pimozide','Concurrent/recent MAOI use, concurrent pimozide, mania','Adults: start 50 mg once daily, up to 200 mg. Often preferred SSRI in cardiac disease and breastfeeding. Taper to stop.','C','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d82','Diazepam (anxiolytic)','Valium','Benzodiazepine','Short-term anxiety, alcohol withdrawal, status epilepticus, muscle spasm','Sedation, dependence, tolerance, respiratory depression, falls in the elderly','Alcohol, opioids (fatal respiratory depression), other CNS depressants, CYP3A4 inhibitors','Severe respiratory insufficiency, sleep apnea, myasthenia gravis, severe hepatic impairment','Adults: anxiety 2-10 mg 2-4 times daily short-term only. Controlled substance — risk of dependence; limit to 2-4 weeks. Do not stop abruptly.','D','US-FDA (legacy)',0,1,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d83','Haloperidol','Serenace, Haldol','Typical antipsychotic','Schizophrenia, acute psychosis, mania, severe agitation, nausea (palliative)','Extrapyramidal symptoms, tardive dyskinesia, QT prolongation, neuroleptic malignant syndrome, sedation','QT-prolonging drugs, CNS depressants, levodopa (antagonism), CYP inhibitors','Parkinson disease, Lewy body dementia, comatose states, significant QT prolongation','Adults: 1.5-5 mg 2-3 times daily orally; lower in elderly. IM for acute agitation. Monitor for extrapyramidal effects and QT.','C','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d84','Chlorpromazine','Largactil, Thorazine','Typical antipsychotic (phenothiazine)','Schizophrenia, psychosis, severe agitation, intractable hiccups, nausea','Sedation, postural hypotension, extrapyramidal symptoms, photosensitivity, QT prolongation, weight gain','Antihypertensives, CNS depressants, QT-prolonging drugs, anticholinergics','Comatose states, bone marrow suppression, phaeochromocytoma; caution in cardiovascular disease','Adults: 25-100 mg 3 times daily, adjusted to response. Sedating. Advise photosensitivity precautions. Lower doses in the elderly.','C','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d85','Risperidone','Risperdal, Sizodon','Atypical antipsychotic','Schizophrenia, bipolar mania, severe aggression/agitation','Weight gain, hyperprolactinemia, extrapyramidal symptoms (dose-related), sedation, orthostatic hypotension','Antihypertensives, CNS depressants, carbamazepine, CYP2D6 inhibitors','Known hypersensitivity; caution in elderly with dementia (increased stroke/mortality)','Adults: 2-6 mg daily in 1-2 divided doses. Elderly/first episode: lower doses. Increase gradually to limit extrapyramidal effects.','C','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d86','Olanzapine','Zyprexa, Oleanz','Atypical antipsychotic','Schizophrenia, bipolar disorder, acute mania','Marked weight gain, hyperglycemia/diabetes, dyslipidemia, sedation, dizziness','CNS depressants, antihypertensives, fluvoxamine (raises levels), carbamazepine (lowers levels)','Known hypersensitivity; caution with dementia in elderly (increased mortality), narrow-angle glaucoma','Adults: 5-10 mg once daily, usual 5-20 mg. Monitor weight, glucose, and lipids. Sedating — often taken at night.','C','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d87','Carbamazepine','Tegretol, Carbatol','Anticonvulsant/mood stabilizer','Focal and generalized tonic-clonic seizures, trigeminal neuralgia, bipolar disorder','Dizziness, diplopia, hyponatremia, rash (SJS/TEN — screen HLA-B*1502 in at-risk groups), blood dyscrasias','Many CYP3A4 interactions: oral contraceptives, warfarin, macrolides, grapefruit; autoinduction','Atrioventricular block, history of bone marrow depression, acute porphyria, concurrent/recent MAOI use','Adults: start 100-200 mg 1-2 times daily, titrate slowly to 800-1200 mg/day. Modified-release reduces side effects. Monitor sodium/blood counts.','D','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d88','Sodium Valproate','Epilim, Depakote','Anticonvulsant/mood stabilizer','Generalized and focal epilepsy, absence seizures, bipolar disorder, migraine prophylaxis','Weight gain, tremor, hair loss, hepatotoxicity, thrombocytopenia, teratogenicity (high risk)','Aspirin, warfarin, lamotrigine (raises levels), carbapenems (lower levels)','Pregnancy and women of childbearing potential without a pregnancy-prevention programme, hepatic impairment, urea cycle disorders, mitochondrial disorders','Adults: 600 mg-2 g/day in divided doses. High teratogenic risk — avoid in females able to become pregnant unless no alternative and strict conditions. Monitor LFTs.','X','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d89','Phenytoin','Dilantin, Epanutin','Anticonvulsant','Focal and generalized tonic-clonic seizures, status epilepticus','Gum hyperplasia, hirsutism, ataxia, nystagmus, rash (SJS), osteomalacia; narrow therapeutic index','Warfarin, oral contraceptives, many CYP inducers/inhibitors, folate, isoniazid','Sinus bradycardia, second/third-degree heart block, sino-atrial block (IV), porphyria','Adults: 200-300 mg daily, adjusted to levels (target 10-20 mg/L). Non-linear kinetics — small dose changes cause large level changes. Monitor levels.','D','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d90','Phenobarbital','Phenobarbitone, Luminal','Barbiturate anticonvulsant','Epilepsy (including in low-resource settings), status epilepticus, neonatal seizures','Sedation, cognitive impairment, dependence, rash, respiratory depression (high dose), hepatic enzyme induction','Oral contraceptives, warfarin, many CYP3A4 substrates, CNS depressants, alcohol','Severe respiratory depression, porphyria, marked hepatic impairment','Adults: 60-180 mg at night. Controlled substance. Withdraw gradually. Enzyme inducer — check interactions (contraceptives, warfarin).','D','US-FDA (legacy)',0,1,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d91','Levetiracetam','Keppra, Levipil','Anticonvulsant','Focal and generalized seizures (mono- or adjunctive therapy)','Somnolence, irritability, behavioral/mood changes, dizziness','Few pharmacokinetic interactions; additive CNS depression with alcohol/sedatives','Known hypersensitivity','Adults: start 250-500 mg twice daily, up to 1500 mg twice daily. Reduce dose in renal impairment. Do not stop abruptly.','C','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d92','Trihexyphenidyl (Benzhexol)','Artane, Pacitane','Antimuscarinic (anti-parkinsonian)','Drug-induced extrapyramidal symptoms/parkinsonism, Parkinson disease tremor (adjunct)','Dry mouth, blurred vision, constipation, urinary retention, confusion (especially elderly)','Other anticholinergics, antipsychotics (may mask tardive dyskinesia), alcohol','Narrow-angle glaucoma, urinary retention, GI obstruction, myasthenia gravis','Adults: start 1 mg daily, titrate to 5-15 mg/day in divided doses. Used to counter antipsychotic-induced parkinsonism. Avoid abrupt withdrawal.','C','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d93','Gabapentin','Neurontin, Gabantin','Anticonvulsant/neuropathic agent','Neuropathic pain, focal seizures (adjunct)','Drowsiness, dizziness, peripheral edema, weight gain, ataxia','Antacids (reduced absorption), opioids (increased sedation/respiratory depression), alcohol','Known hypersensitivity; caution with opioids and in renal impairment','Adults: start 300 mg at night, titrate to 900-3600 mg/day in 3 divided doses. Reduce in renal impairment. Taper to stop.','C','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL);

-- ============================================================
-- RESPIRATORY (d94 - d103)
-- ============================================================
INSERT OR IGNORE INTO drugs
  (id, generic_name, brand_names, drug_class, uses, side_effects, interactions, contraindications, dosage_notes, pregnancy_category, pregnancy_category_system, otc, controlled, source_reference, source_url, reviewed_by, reviewed_at)
VALUES
  ('d94','Salbutamol (Albuterol)','Ventolin, Asthalin','Short-acting beta-2 agonist','Asthma and COPD symptom relief, acute bronchospasm, exercise-induced bronchospasm','Tremor, palpitations, tachycardia, headache, hypokalemia (high dose), muscle cramps','Beta-blockers (antagonism), other sympathomimetics, high-dose corticosteroids/diuretics (hypokalemia)','Hypersensitivity; caution in significant cardiovascular disease and hyperthyroidism','Adults: inhaler 100-200 mcg (1-2 puffs) as needed, up to 4 times daily. Frequent need signals poor control — review therapy. Use a spacer for technique.','C','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d95','Beclometasone (inhaled)','Becotide, Clenil, Beclate','Inhaled corticosteroid','Asthma maintenance (anti-inflammatory preventer)','Oral candidiasis, hoarseness, sore throat; adrenal suppression/growth effects at high dose','Ritonavir and strong CYP3A4 inhibitors (raised systemic levels)','Hypersensitivity; not for acute relief of bronchospasm','Adults: 100-400 mcg twice daily depending on severity. Rinse mouth after use to prevent thrush. Not a reliever — use daily for control.','C','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d96','Salmeterol-Fluticasone','Seretide, Foracort (analogous)','LABA/inhaled corticosteroid combination','Asthma and COPD maintenance where a combination is indicated','Oral candidiasis, hoarseness, tremor, palpitations, headache','Beta-blockers, strong CYP3A4 inhibitors (ritonavir, ketoconazole)','Monotherapy for acute asthma; hypersensitivity; LABA not to be used without an inhaled corticosteroid in asthma','Adults: one inhalation twice daily at the strength prescribed. Not for acute relief. Rinse mouth after use. Review inhaler technique.','C','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d97','Ipratropium Bromide','Atrovent','Short-acting antimuscarinic bronchodilator','COPD and asthma (adjunct), acute bronchospasm (with salbutamol)','Dry mouth, cough, headache, blurred vision if sprayed in eyes, urinary retention','Other antimuscarinics','Hypersensitivity; caution in narrow-angle glaucoma (avoid eye exposure) and bladder outflow obstruction','Adults: 20-40 mcg (1-2 puffs) 3-4 times daily; nebulised 250-500 mcg in acute settings. Often combined with salbutamol.','B','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d98','Montelukast','Singulair, Montair','Leukotriene receptor antagonist','Asthma prophylaxis (add-on), allergic rhinitis, exercise-induced bronchoconstriction','Headache, GI upset, neuropsychiatric effects (mood/behavior changes, sleep disturbance)','Phenobarbital/rifampicin (reduced levels)','Hypersensitivity; counsel on neuropsychiatric effects','Adults: 10 mg once daily in the evening. Children: 4-5 mg once daily by age. Not for acute attacks. Report mood/behavior changes.','B','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d99','Theophylline (Aminophylline)','Nuelin, Phyllocontin','Methylxanthine bronchodilator','COPD and asthma (add-on where inhalers insufficient)','Nausea, tremor, palpitations, arrhythmias, seizures; narrow therapeutic index','Ciprofloxacin/macrolides (raise levels), phenytoin/rifampicin (lower levels), smoking (lowers levels)','Uncontrolled arrhythmias; caution in cardiac disease, hyperthyroidism, epilepsy','Adults: modified-release 200-400 mg twice daily, adjusted to blood levels (target 10-20 mg/L). Monitor levels; many interactions.','C','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d100','Prednisolone (respiratory short course)','Prednisolone','Corticosteroid','Acute asthma and COPD exacerbations (short course)','Insomnia, mood change, raised glucose, appetite increase (short courses); as for systemic steroids','NSAIDs, antidiabetics, live vaccines, diuretics','Systemic infection without cover; caution in diabetes and peptic ulcer','Adults: 40 mg once daily for 5 days for acute asthma (no taper needed for short courses). Take in the morning with food.','C','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d101','Cetirizine','Zyrtec, Alerid','Second-generation antihistamine','Allergic rhinitis, urticaria, allergic conjunctivitis','Mild drowsiness, dry mouth, headache','Alcohol and CNS depressants (additive sedation)','Hypersensitivity; reduce dose in significant renal impairment','Adults: 10 mg once daily. Children (2-6 yr): 5 mg daily. Less sedating than older antihistamines. Available OTC.','B','US-FDA (legacy)',1,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d102','Guaifenesin','Robitussin, Mucinex','Expectorant','Productive cough — loosening chest congestion','Nausea, vomiting, dizziness (uncommon)','Few significant interactions','Hypersensitivity','Adults: 200-400 mg every 4 hours, max 2.4 g/day. Drink plenty of fluids. Symptomatic relief only; see a doctor if cough persists beyond 1 week.','C','US-FDA (legacy)',1,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d103','Dextromethorphan','Benylin DM, Robitussin DM','Antitussive (cough suppressant)','Dry, non-productive cough','Dizziness, drowsiness, nausea; abuse potential at high doses','MAOIs (serotonin syndrome), SSRIs, alcohol, CNS depressants','Concurrent/recent MAOI use; children under 6 (avoid); productive cough','Adults: 10-20 mg every 4 hours or 30 mg every 6-8 hours, max 120 mg/day. Not for productive cough. Avoid in young children.','C','US-FDA (legacy)',1,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL);

