INSERT OR IGNORE INTO drugs
  (id, generic_name, brand_names, drug_class, uses, side_effects, interactions, contraindications, dosage_notes, pregnancy_category, pregnancy_category_system, otc, controlled, source_reference, source_url, reviewed_by, reviewed_at)
VALUES
  ('d150','Tenofovir Disoproxil-Lamivudine-Dolutegravir (TLD)','TLD, Acriptega','Fixed-dose ART (NRTI/NRTI/INSTI)','First-line HIV treatment (preferred regimen)','Headache, insomnia, weight gain, nausea; tenofovir renal/bone effects','Rifampicin (needs extra dolutegravir dose), polyvalent cations/antacids (separate dosing), metformin','Hypersensitivity; caution in significant renal impairment (tenofovir DF)','Adults: one tablet once daily. Separate from antacids/iron/calcium (dolutegravir chelation). Adherence critical; monitor renal function.','B','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d151','Dolutegravir','Tivicay','Integrase strand transfer inhibitor','HIV treatment (component of first-line ART)','Headache, insomnia, weight gain, GI upset, rare hypersensitivity','Rifampicin, carbamazepine, polyvalent cations/antacids, metformin','Concurrent dofetilide; hypersensitivity','Adults: 50 mg once daily (twice daily with certain inducers like rifampicin). Take antacids/mineral supplements well separated. Monitor adherence.','B','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d152','Tenofovir DF-Lamivudine','TL, Cipla TL','Dual NRTI backbone','HIV treatment backbone, HIV pre-exposure prophylaxis (PrEP), hepatitis B','Nausea, renal impairment, reduced bone density, lactic acidosis (rare)','Nephrotoxic drugs, NSAIDs (renal), didanosine','Severe renal impairment (dose adjust); hypersensitivity','Adults: one tablet once daily (tenofovir DF 300 mg/lamivudine 300 mg). PrEP: once daily. Monitor renal function; do not stop abruptly in HBV coinfection.','B','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d153','Efavirenz','Sustiva, Stocrin','Non-nucleoside reverse transcriptase inhibitor','HIV treatment (alternative regimens)','CNS effects (vivid dreams, dizziness, mood changes), rash, raised lipids, gynecomastia','Rifampicin, methadone, contraceptives, many CYP3A4 substrates','Severe hepatic impairment, history of severe psychiatric illness (caution), concurrent contraindicated CYP substrates','Adults: 600 mg once daily at bedtime (empty stomach reduces CNS effects). Take on an empty stomach; counsel on transient CNS effects.','D','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d154','Nevirapine','Viramune','Non-nucleoside reverse transcriptase inhibitor','HIV treatment (specific regimens), prevention of mother-to-child transmission','Rash (including SJS), hepatotoxicity (can be severe, early), fever','Rifampicin, contraceptives, methadone, ketoconazole','Moderate-to-severe hepatic impairment; higher baseline CD4 counts (initiation risk)','Adults: 200 mg once daily for 14 days (lead-in) then 200 mg twice daily to reduce rash risk. Monitor liver function; stop if severe rash/hepatitis.','B','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d155','Abacavir-Lamivudine','Kivexa, ABC/3TC','Dual NRTI backbone','HIV treatment backbone (alternative to tenofovir)','Hypersensitivity reaction (HLA-B*5701-linked, can be fatal), nausea, headache','Methadone, alcohol (abacavir metabolism)','HLA-B*5701 positivity; prior abacavir hypersensitivity; moderate/severe hepatic impairment','Adults: one tablet once daily. Screen HLA-B*5701 before starting; never rechallenge after a hypersensitivity reaction. Counsel on warning symptoms.','C','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d156','Lopinavir-Ritonavir','Aluvia, Kaletra','Protease inhibitor (boosted)','HIV treatment (second-line/specific populations)','Diarrhea, nausea, dyslipidemia, raised liver enzymes, QT/PR prolongation','Many CYP3A4 interactions: rifampicin, statins, ergot, some antiarrhythmics','Concurrent drugs highly dependent on CYP3A4 with narrow index (ergot, some statins), severe hepatic impairment','Adults: 400/100 mg twice daily (or 800/200 mg once daily in some cases). Take with food. Extensive interactions — review co-medications.','C','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL),
  ('d157','Zidovudine','Retrovir, AZT','Nucleoside reverse transcriptase inhibitor','HIV treatment (specific regimens), prevention of mother-to-child transmission','Anemia, neutropenia, headache, myopathy, lactic acidosis','Myelosuppressive drugs, ganciclovir, stavudine (antagonism)','Severe anemia/neutropenia; caution in bone marrow suppression','Adults: 300 mg twice daily (regimen-dependent). Monitor full blood count for marrow suppression. Largely superseded by better-tolerated agents.','C','US-FDA (legacy)',0,0,'WHO EML 2023; Ghana STG 2017 (AI-drafted — pending pharmacist review)','https://list.essentialmeds.org/',NULL,NULL);

